import moment from 'moment'
import dayjs from '../src'
import customParseFormat from '../src/plugin/customParseFormat'
import '../src/locale/zh-cn'
import '../src/locale/ja'
dayjs.extend(customParseFormat)
it('r2', () => {
  const out = []
  const format = 'YYYY年M月D日Ah点mm分ss秒'
  const input = '2018-05-02 01:02:03'
  const date = dayjs(input).locale('zh-cn').format(format)
  out.push('2a:' + JSON.stringify(date))
  out.push('2b:' + dayjs(date, format, 'zh-cn').format('YYYY-MM-DD HH:mm:ss'))
  // full round trip for all hours
  let bad = []
  for (let h = 0; h < 24; h += 1) {
    const src = dayjs('2018-05-02 00:02:03').hour(h)
    const s = src.locale('zh-cn').format(format)
    const back = dayjs(s, format, 'zh-cn').format('YYYY-MM-DD HH:mm:ss')
    if (back !== src.format('YYYY-MM-DD HH:mm:ss')) bad.push(`${h}:${s}->${back}`)
  }
  out.push('2c roundtrip bad=' + JSON.stringify(bad))
  // ja
  const jf = 'YYYY年M月D日Ah時mm分ss秒'
  let badJa = []
  for (let h = 0; h < 24; h += 1) {
    const src = dayjs('2018-05-02 00:02:03').hour(h)
    const s = src.locale('ja').format(jf)
    const back = dayjs(s, jf, 'ja').format('YYYY-MM-DD HH:mm:ss')
    if (back !== src.format('YYYY-MM-DD HH:mm:ss')) badJa.push(`${h}:${s}->${back}`)
  }
  out.push('2d ja bad=' + JSON.stringify(badJa))
  // en AM/PM still fine
  out.push('2e:' + dayjs('2018-05-02 12:00 am', 'YYYY-MM-DD hh:mm a').format('HH:mm'))
  out.push('2f:' + dayjs('2018-05-02 12:00 pm', 'YYYY-MM-DD hh:mm a').format('HH:mm'))
  out.push('2g:' + dayjs('2.5.18 1:2:3.4 PM -0100', 'D.M.YY H:m:s.S A ZZ').valueOf())
  out.push('2h:' + moment('2.5.18 1:2:3.4 PM -0100', 'D.M.YY H:m:s.S A ZZ').valueOf())
  out.push('2i:' + dayjs('05/02/69 1:02:03.004 AM +01:00 (CET)', 'MM/DD/YY h:mm:ss.SSS A Z (z)').valueOf())
  out.push('2j:' + moment('05/02/69 1:02:03.004 AM +01:00 (CET)', 'MM/DD/YY h:mm:ss.SSS A Z (z)').valueOf())
  throw new Error(out.join(' | '))
})
