import moment from 'moment'
import dayjs from '../src'
import weekYear from '../src/plugin/weekYear'
import weekOfYear from '../src/plugin/weekOfYear'
import 'moment/locale/en-gb'
dayjs.extend(weekYear).extend(weekOfYear)
it('weekYear matches moment broadly', () => {
  const bad = []
  for (let y = 2015; y <= 2025; y += 1) {
    for (let m = 0; m < 12; m += 1) {
      for (const day of [1, 2, 3, 4, 5, 15, 28, 30, 31]) {
        const s = `${y}-${String(m + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`
        const dj = dayjs(s)
        if (!dj.isValid()) continue
        ;['en-gb', 'en'].forEach((loc) => {
          const a = dj.locale(loc).weekYear()
          const b = moment(s).locale(loc).weekYear()
          if (Number.isNaN(b)) return
          if (a !== b) bad.push(`${s}/${loc}: dayjs=${a} moment=${b}`)
        })
      }
    }
  }
  console.log('MISMATCHES=' + bad.length)
  console.log(bad.slice(0, 30).join('\n'))
})
EOF
npx jest test/zz_final.test.js --coverage=false 2>&1 | grep -E "MISMATCHES|20[0-9]{2}-" | head -35; rm -f test/zz_final.test.js

